    # =====================================================================
    # Lingo Access Evaluation Methods
    # These methods mirror the original Lingo world's access rule logic
    # =====================================================================

    _worldgen_settings: Dict[str, Any] = None

    def _load_worldgen_settings(self) -> Dict[str, Any]:
        """Load settings from _worldgen_settings.json."""
        if self._worldgen_settings is None:
            settings_path = Path(__file__).parent / "_worldgen_settings.json"
            if settings_path.exists():
                with open(settings_path, 'r') as f:
                    self._worldgen_settings = json.load(f)
            else:
                self._worldgen_settings = {}
        return self._worldgen_settings

    def lingo_can_use_entrance(self, state: CollectionState, target_room: str,
                               door_room: str, door_name: str) -> bool:
        """Check if an entrance can be used (door can be opened)."""
        return self._lingo_can_open_door(state, door_room, door_name)

    def lingo_can_use_location(self, state: CollectionState, location_name: str) -> bool:
        """Check if a location can be accessed based on its access requirements."""
        if location_name not in location_table:
            return True  # Unknown location, assume accessible

        loc_data = location_table[location_name]
        if not hasattr(loc_data, 'access') or loc_data.access is None:
            return True  # No access requirements

        return self._lingo_can_satisfy_requirements(state, loc_data.access)

    def _lingo_can_satisfy_requirements(self, state: CollectionState, access: Dict[str, Any]) -> bool:
        """Check if access requirements are satisfied."""
        if not access:
            return True

        settings = self._load_worldgen_settings()

        # Check room requirements
        for req_room in access.get('rooms', []):
            if not state.can_reach(req_room, "Region", self.player):
                return False

        # Check door requirements
        for door_info in access.get('doors', []):
            door_room = door_info.get('room') if isinstance(door_info, dict) else None
            door_name = door_info.get('door') if isinstance(door_info, dict) else None
            if door_room and door_name:
                if not self._lingo_can_open_door(state, door_room, door_name):
                    return False

        # Check color requirements (if shuffle_colors is enabled)
        if settings.get('shuffle_colors'):
            for color in access.get('colors', []):
                color_item = color.capitalize() if isinstance(color, str) else color
                if not state.has(color_item, self.player):
                    return False

        # Check item requirements
        for item in access.get('items', []):
            if not state.has(item, self.player):
                return False

        # Check progression requirements
        for item, count in access.get('progression', {}).items():
            if not state.has(item, self.player, count):
                return False

        # Check mastery requirement
        if access.get('the_master'):
            if not self.lingo_can_use_mastery_location(state):
                return False

        # Check postgame flag
        if access.get('postgame'):
            if state.has("Prevent Victory", self.player):
                return False

        return True

    def _lingo_can_open_door(self, state: CollectionState, room: str, door: str) -> bool:
        """Check if a door can be opened."""
        settings = self._load_worldgen_settings()

        # Check if this door requires an item
        item_by_door = settings.get('item_by_door', {})
        if room in item_by_door and door in item_by_door[room]:
            item_name = item_by_door[room][door]

            # Check for progressive items
            progressive_items = settings.get('PROGRESSIVE_ITEMS', {})
            if item_name in progressive_items:
                prog_doors = settings.get('PROGRESSIVE_DOORS_BY_ROOM', {})
                if room in prog_doors and door in prog_doors[room]:
                    progression_index = prog_doors[room][door].get('index', 1)
                    return state.has(item_name, self.player, progression_index)

            return state.has(item_name, self.player)

        # Check door requirements (rooms, colors, items, etc.)
        door_reqs = settings.get('door_reqs', {})
        if room in door_reqs and door in door_reqs[room]:
            return self._lingo_can_satisfy_requirements(state, door_reqs[room][door])

        # No requirements found - door is accessible
        return True

    def lingo_can_use_mastery_location(self, state: CollectionState) -> bool:
        """Check if mastery location requirements are met."""
        settings = self._load_worldgen_settings()
        mastery_reqs = settings.get('mastery_reqs', [])
        mastery_achievements = settings.get('mastery_achievements', 21)

        if not mastery_reqs or mastery_achievements <= 0:
            return True

        satisfied_count = 0
        for access_req in mastery_reqs:
            if self._lingo_can_satisfy_requirements(state, access_req):
                satisfied_count += 1

        return satisfied_count >= mastery_achievements

    def lingo_can_use_level_2_location(self, state: CollectionState) -> bool:
        """Check if level 2 location requirements are met."""
        settings = self._load_worldgen_settings()
        counting_panel_reqs = settings.get('counting_panel_reqs', {})
        level_2_requirement = settings.get('level_2_requirement', 223)

        if level_2_requirement <= 1:
            return True

        counted_panels = 0
        state.update_reachable_regions(self.player)

        for region in state.reachable_regions[self.player]:
            region_name = region.name
            if region_name not in counting_panel_reqs:
                continue

            region_panel_reqs = counting_panel_reqs[region_name]
            for access_req, panel_count in region_panel_reqs:
                if self._lingo_can_satisfy_requirements(state, access_req):
                    counted_panels += panel_count

            if counted_panels >= level_2_requirement - 1:
                return True

        return counted_panels >= level_2_requirement - 1
